package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import com.networknt.schema.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.math.BigInteger;
public final class FormalInvocationHttpSchema {
 private final FormalInvocationSchema json;private final Map<String,JsonSchema> definitions=new HashMap<>();
 public FormalInvocationHttpSchema(FormalInvocationSchema json)throws Exception{this.json=json;try(var in=getClass().getResourceAsStream("/formal-invocation-http.schema.json")){if(in==null)throw new IllegalStateException();var root=json.parse(new String(in.readAllBytes(),StandardCharsets.UTF_8));var factory=JsonSchemaFactory.getInstance(SpecVersion.VersionFlag.V202012);for(String name:List.of("Reserve","BeginSend","Receipt","Cancel","Unknown","CancelReceipt","CancelRecovery","WorkerClaim","WorkerIdentity")){var wrapper=((com.fasterxml.jackson.databind.node.ObjectNode)root.deepCopy()).put("$ref","#/$defs/"+name);definitions.put(name,factory.getSchema(wrapper));}}}
 JsonNode read(String definition,byte[] bytes)throws Exception{var n=json.parse(new String(bytes,StandardCharsets.UTF_8));if(!definitions.containsKey(definition)||!definitions.get(definition).validate(n).isEmpty())throw new TenantAccessException(ErrorCode.SCHEMA_INVALID);if("Reserve".equals(definition))json.require("RequestParameters",n.required("request_parameters"));return n;}
 void validate(String definition,JsonNode n){if(!definitions.containsKey(definition)||!definitions.get(definition).validate(n).isEmpty())throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
 RunTokenAuthority.ActionRequest action(JsonNode body){var n=body.required("worker_action");var s=n.required("scope");return new RunTokenAuthority.ActionRequest(t(n,"run_id"),t(n,"step_id"),t(n,"action_id"),new BigInteger(t(n,"lease_generation")),t(n,"input_sha256"),t(n,"arguments_sha256"),t(n,"kind"),t(n,"tool_version"),new PermissionProtocol.Scope(t(s,"tenant_id"),t(s,"project_id"),t(s,"resource_kind"),t(s,"resource_id")),t(n,"action"),t(n,"purpose"));}
 private static String t(JsonNode n,String k){return n.required(k).textValue();}
}
